refentry.refsect1:
&reftitle.description;
boolarray_is_list arrayarray
दिइएको array एउटा list हो कि होइन भनी निर्धारण गर्दछ। कुनै &array; लाई एउटा list तब मानिन्छ जब यसका keys हरू from 0 देखि count($array)-1 सम्मका क्रमिक सङ्ख्याहरू मिलेर बनेका हुन्छन्।

  &reftitle.examples;



    array_is_list को उदाहरण


<?php
var_dump(array_is_list([])); // true
var_dump(array_is_list(['apple', 2, 3])); // true
var_dump(array_is_list([0 => 'apple', 'orange'])); // true

// The array does not start at 0
var_dump(array_is_list([1 => 'apple', 'orange'])); // false

// The keys are not in the correct order
var_dump(array_is_list([1 => 'apple', 0 => 'orange'])); // false

// Non-integer keys
var_dump(array_is_list([0 => 'apple', 'foo' => 'bar'])); // false

// Non-consecutive keys
var_dump(array_is_list([0 => 'apple', 2 => 'bar'])); // false
?>
